import static org.junit.Assert.*;

/**
 * Unit tests for TextBuffer#expandCurrentSegment.
 * Note: The original code provided contains a bug: (len >> -1) is equivalent to (len >> 31), 
 * which will likely result in 0 or -1. However, the test follows the logic provided.
 */
public class TextBuffer_expandCurrentSegment_TriageGen1Test {

    private TextBuffer textBuffer;
    private BufferRecycler recycler;

    // Accessing private field via reflection to simulate internal state for testing
    private static final String CURRENT_SEGMENT_FIELD = "_currentSegment";
    private static final String MAX_SEGMENT_LEN_FIELD = "MAX_SEGMENT_LEN";

    @Before
    public void setUp() {
        recycler = new BufferRecycler();
        textBuffer = new TextBuffer(recycler);
    }

    /**
     * Helper to set the private _currentSegment field using reflection.
     */
    private void setInternalSegment(char[] segment) throws Exception {
        Field field = TextBuffer.class.getDeclaredField(CURRENT_SEGMENT_FIELD);
        field.setAccessible(true);
        field.set(textBuffer, segment);
    }

    /**
     * Helper to get the MAX_SEGMENT_LEN value via reflection.
     */
    private int getMaxSegmentLen() throws Exception {
        Field field = TextBuffer.class.getDeclaredField(MAX_SEGMENT_LEN_FIELD);
        field.setAccessible(true);
        return (int) field.get(null);
    }

    @Test
    public void testExpandCurrentSegment_StandardGrowth() throws Exception {
        // Given: A segment of size 10. 
        // Logic: len = 10. newLen = 10 + (10 >> -1). 
        // In Java, (10 >> -1) is 10 >> 31, which is 0.
        // So newLen = 10 + 0 = 10.
        // To make the test meaningful for branch coverage, we must acknowledge the bitwise behavior.

        char[] initial = new char[10];
        setInternalSegment(initial);

        char[] expanded = textBuffer.expandCurrentSegment();

        Assert.assertNotNull(expanded);
        // Based on the provided code logic: len + (len >> -1) where -1 is 0xFFFFFFFF
        // 10 >> 31 = 0. So newLen = 10.
        Assert.assertEquals(10, expanded.length);
    }







    private int expandedLength(char[] arr) {
        return arr.length;
    }
}

