        field.setAccessible(true);
        return (int) field.get(null);
    }



    @Test
    public void testExpandCurrentSegment_LargeGrowthPath() throws Exception {
        // To trigger the 'if (newLen > MAX_SEGMENT_LEN)' branch,
        // we need to manipulate the state so that len + (len >> -1) > MAX_SEGMENT_LEN.
        // Since (len >> -1) is 0, we need to force a state where the initial calculation 
        // would exceed MAX_SEGMENT_LEN. 
        // However, since (len >> -1) is always 0 for positive len, newLen will equal len.
        // The only way to trigger the branch is if len > MAX_SEGMENT_LEN initially.

        int maxLen = getMaxSegmentLen();
        char[] largeSegment = new char[maxLen + 1];
        setInternalSegment(largeSegment);

        // len = maxLen + 1
        // newLen = (maxLen + 1) + 0 = maxLen + 1
        // newLen > MAX_SEGMENT_LEN is true.
        // newLen = len + (len >> 2)

        char[] expanded = textBuffer.expandCurrentSegment();

        int expectedLen = (maxLen + 1) + ((maxLen + 1) >> 2);
        Assert.assertEquals(expectedLen, expanded.length);
    }





    private int expandedLength(char[] arr) {
        return arr.length;
    }
}

